  const clean=(rs:any[])=>[...new Map(rs.map(r=>[Date.parse(r.minute_bucket),r])).values()].sort((a:any,b:any)=>Date.parse(a.minute_bucket)-Date.parse(b.minute_bucket));
  byKey.forEach((rs,k)=>byKey.set(k,clean(rs)));
  const currentTimes=[...(current.options||[]),...(current.chain||[]),...(current.market||[])].map(r=>Date.parse(r.minute_bucket)).filter(Number.isFinite);
