    valid.forEach(r=>{const d=day(r.minute_bucket);if(!daily.has(d))daily.set(d,[]);daily.get(d)!.push(r);});
    function range(rows:any[],scope:string){if(!rows.length)return;const hi=rows.reduce((a,b)=>b[s.field]>a[s.field]?b:a),lo=rows.reduce((a,b)=>b[s.field]<a[s.field]?b:a);ranges.push({identity:s.identity,field:s.field,scope,high:hi[s.field],highAt:hi.minute_bucket,low:lo[s.field],lowAt:lo.minute_bucket,firstAt:rows[0].minute_bucket,lastAt:rows.at(-1).minute_bucket,samples:rows.length,days:new Set(rows.map(r=>day(r.minute_bucket))).size,firstTieOnly:true});}
