 if(!allPoints.length)return '<div class="pcr-placeholder"><div><b>PCR + spot await recorded observations</b><p class="muted">No synthetic curve · no invented changes</p></div></div>';
 const times=allPoints.map(p=>Date.parse(p.at)),start=Math.min(...times),end=Math.max(...times),x=t=>82+(t-start)/(end-start||1)*756;
 const bounds=rows=>{if(!rows.length)return null;let lo=Math.min(...rows.map(p=>p.value)),hi=Math.max(...rows.map(p=>p.value)),pad=(hi-lo)*.12||Math.max(Math.abs(lo)*.01,.01);return {lo:lo-pad,hi:hi+pad};};
