function inspectPcrEvent(target){const symbol=target.dataset.symbol,id=Number(target.dataset.event),m=pcrCache[symbol],e=m?.events.find(e=>e.id===id);if(!e)return;const stars=e.stars===null?'Change ★ rating unavailable / not applicable':'Change '+'★'.repeat(e.stars)+'☆'.repeat(5-e.stars);const follow=e.spotFollow.map(f=>f.label+': '+(f.delta===null?'unavailable':sign(f.delta,2)+' spot points @ '+when(f.at))).join(' | ');const alignment=e.pcrDelta===null||e.spotDelta===null?'PCR/spot interval comparison unavailable':e.pcrDelta===0||e.spotDelta===0?'One or both unchanged':Math.sign(e.pcrDelta)===Math.sign(e.spotDelta)?'PCR and spot moved in the same direction':'PCR and spot moved in opposite directions';$('pcr-inspect-'+symbol).textContent=graphEventText(e)+' | '+stars+' | '+alignment+' | Spot Δ '+sign(e.spotDelta,2)+' points | Observed spot afterward: '+follow+(e.context?' | '+e.context:'')+' | Expiry '+m.expiry;}
