 const oiBars=fields=>{const r=fields.find(r=>r.field==='oi');if(!r||r.from.value===null||r.to.value===null)return '<p class="annex-unavailable">OI comparison coverage unavailable.</p>';const maximum=Math.max(r.from.value,r.to.value);if(maximum<=0)return '<p>Recorded OI: '+fmt(r.from.value,0)+' → '+fmt(r.to.value,0)+'</p>';return '<div aria-label="Exact option OI comparison">'+[['Earlier',r.from],['Latest',r.to]].map(([label,p])=>'<div class="pctrow"><span>'+label+'</span><div class="track"><div class="bar" style="width:'+p.value/maximum*100+'%;background:var(--cyan)"></div></div><span>'+fmt(p.value,0)+'</span></div><small>'+esc(when(p.at))+'</small>').join('')+'</div>';};
