 const bridgeFields=compact(a.bridge),differentTimes=['from','to'].some(side=>new Set(bridgeFields.map(r=>Date.parse(r[side].at)).filter(Number.isFinite)).size>1);
 $('annex-bridge').innerHTML=(a.priorDate?esc(a.priorDate)+' → '+esc(a.tradeDate):'Previous session unavailable')+'<small style="display:block">Sampled last observations; not official closes</small>'+bridgeFields.map(r=>'<div>'+esc(r.label)+' '+colored(r.delta)+'<small style="display:block">'+esc(when(r.from.at)+' → '+when(r.to.at))+'</small></div>').join('')+(differentTimes?'<small class="annex-warning">Different sampled endpoint times; alignment unverified.</small>':'');
 $('annex-persisted').innerHTML=a.persisted.length?'<small>Unchanged at both sampled endpoints:</small><br>'+ a.persisted.map(r=>esc(r.label)+' '+fmt(r.value,3)+' <small>'+esc(when(r.from)+' → '+when(r.at))+'</small>').join('<br>'):'No unchanged endpoints verified. Intraday persistence requires recorded history.';
