async function ensureAnnexMemory(){
 const symbol=$('detail-symbol').value,date=loadedScope.date;if(!date||memoryBusy||pcrMemoryBusy||busy)return;
 const dates=recordedDates.filter(d=>d<date).slice(-6),cached=memory[symbol];
 if(!cached||JSON.stringify(cached.requested)!==JSON.stringify(dates)){$('memory-days').value='6';await loadMemory();}
 if(loadedScope.date!==date||$('detail-symbol').value!==symbol)return;
 renderDataAnnex();const prior=annexView?.priorDate,key=symbol+'|'+prior;if(!prior||eodCache.has(key))return;
 eodCache.set(key,null);try{const result=await get(symbol+' EOD descriptive summary '+prior,'/api/research/h1-eod-business-backtest-summary?symbol='+symbol+'&date='+prior+'&from=09:15&to=15:30&scope=CORE&top=1');if(result.request?.tradeDate===prior&&result.request?.symbol===symbol)eodCache.set(key,{session:result.session});}catch{}finally{if(loadedScope.date===date&&$('detail-symbol').value===symbol)renderDataAnnex();}
}

